"""Command-line framework: registry, argument reading, context, output rules."""
import os
import re
from datetime import date

from tallybook.dates import parse_date
from tallybook.errors import ConflictError, TallybookError


class UsageError(Exception):
    """The command line itself is wrong: exit status 2."""


class CliError(Exception):
    """The program refused: exit status 1, ``tallybook: message`` on stderr."""

    def __init__(self, message, lines=()):
        Exception.__init__(self, message)
        self.message = message
        self.lines = list(lines)


class Opt:
    """kind: 'value' (one value), 'flag' (no value) or 'repeat' (value, may repeat)."""

    def __init__(self, name, kind="value", required=False, short=None, metavar=None):
        self.name = name
        self.kind = kind
        self.required = required
        self.short = short
        self.metavar = metavar or name.upper()


class Cmd:
    """pos: list of (NAME, kind); kind '1' one, '?' optional, '*' any number, '+' at least one."""

    def __init__(self, words, usage, summary, handler, opts=(), pos=(), needs_book=True):
        self.words = tuple(words)
        self.usage = usage
        self.summary = summary
        self.handler = handler
        self.opts = {o.name: o for o in opts}
        self.shorts = {o.short: o for o in opts if o.short}
        self.pos = list(pos)
        self.needs_book = needs_book


class Node:
    def __init__(self):
        self.children = {}
        self.cmd = None
        self.summary = ""


ROOT = Node()


def command(words, usage, summary, opts=(), pos=(), needs_book=True):
    """Decorator: register ``handler(ctx, args)``; ``words`` like 'tx add'."""

    def register(handler):
        parts = words.split()
        node = ROOT
        for w in parts:
            node = node.children.setdefault(w, Node())
        node.cmd = Cmd(parts, usage, summary, handler, opts, pos, needs_book)
        return handler

    return register


def group_summary(words, summary):
    node = ROOT
    for w in words.split():
        node = node.children.setdefault(w, Node())
    node.summary = summary


class Args:
    def __init__(self, pos, opts):
        self.pos = pos
        self.opts = opts

    def get(self, name, default=None):
        value = self.opts.get(name)
        return default if value is None else value

    def flag(self, name):
        return bool(self.opts.get(name))

    def many(self, name):
        return list(self.opts.get(name) or [])


class HelpRequest(Exception):
    pass


def parse_args(cmd, tokens):
    pos = []
    values = {}
    ddash = False
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        i += 1
        if ddash:
            pos.append(tok)
        elif tok == "--":
            ddash = True
        elif tok in ("-h", "--help"):
            raise HelpRequest()
        elif tok.startswith("--"):
            name, eq, val = tok[2:].partition("=")
            opt = cmd.opts.get(name)
            if opt is None:
                raise UsageError("unknown option: --%s" % name)
            if opt.kind == "flag":
                if eq:
                    raise UsageError("option --%s takes no value" % name)
                if name in values:
                    raise UsageError("option --%s given twice" % name)
                values[name] = True
                continue
            if not eq:
                if i >= len(tokens):
                    raise UsageError("option --%s needs a value" % name)
                val = tokens[i]
                i += 1
            _store(values, opt, val)
        elif tok in cmd.shorts and len(tok) == 2:
            opt = cmd.shorts[tok]
            if i >= len(tokens):
                raise UsageError("option --%s needs a value" % opt.name)
            val = tokens[i]
            i += 1
            _store(values, opt, val)
        else:
            pos.append(tok)
    for opt in cmd.opts.values():
        if opt.required and opt.name not in values:
            raise UsageError("missing required option --%s" % opt.name)
    need = sum(1 for _, k in cmd.pos if k in ("1", "+"))
    maximum = None if any(k in ("*", "+") for _, k in cmd.pos) else len(cmd.pos)
    if len(pos) < need:
        missing = [n for n, k in cmd.pos if k in ("1", "+")][len(pos)]
        raise UsageError("missing argument %s" % missing)
    if maximum is not None and len(pos) > maximum:
        raise UsageError("unexpected argument: %s" % pos[maximum])
    return Args(pos, values)


def _store(values, opt, val):
    if opt.kind == "repeat":
        values.setdefault(opt.name, []).append(val)
    else:
        if opt.name in values:
            raise UsageError("option --%s given twice" % opt.name)
        values[opt.name] = val


_INT = re.compile(r"-?[0-9]{1,18}")


def parse_int(text, what="number", negative=False):
    """A whole number argument: decimal digits, at most 18, optional '-' where allowed."""
    if not isinstance(text, str) or not _INT.fullmatch(text) or (text[0] == "-" and not negative):
        raise CliError("invalid %s '%s': expected a whole number" % (what, text))
    return int(text)


def parse_day(text, what="date"):
    return parse_date(text)


class Context:
    def __init__(self, db_path, today, stdin=None):
        self.db_path = db_path
        self._today = today
        self._stores = []
        self.stdin = stdin

    @property
    def today(self):
        return self._today if self._today is not None else date.today()

    def open_book(self, create=False, allow_old=False):
        from tallybook.storage import LATEST_VERSION, Store

        path = self.db_path
        if not create and not os.path.exists(path):
            raise CliError("no such database: %s (run `tallybook init`)" % path)
        store = Store.open(path, create=create)
        self._stores.append(store)
        if not allow_old and store.version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % store.version)
        return store

    def close(self):
        for s in self._stores:
            try:
                s.close()
            except Exception:
                pass
        self._stores = []

    def read_input(self, path):
        """Text of a file, or standard input for '-'. Bytes are decoded as UTF-8 exactly."""
        import sys

        if path == "-":
            stream = self.stdin if self.stdin is not None else sys.stdin
            buf = getattr(stream, "buffer", None)
            try:
                raw = buf.read() if buf is not None else stream.read()
            except (OSError, ValueError) as err:
                raise CliError("cannot read standard input: %s" % err)
            label = "standard input"
        else:
            label = path
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
            except OSError as err:
                raise CliError("cannot read %s: %s" % (path, err.strerror or err))
        if isinstance(raw, str):
            return raw
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError:
            raise CliError("%s is not valid UTF-8 text" % label)


def input_label(path):
    return "standard input" if path == "-" else path


def wrap_input_errors(path, func, *args):
    """Run a parser on a file's text; prefix its message with the file name."""
    try:
        return func(*args)
    except TallybookError as err:
        raise CliError("%s: %s" % (input_label(path), err.message))

"""The ``tallybook`` command: global options, command lookup, exit statuses, output."""
import os
import sys

from tallybook import __version__
from tallybook.cli import core
from tallybook.cli.core import CliError, HelpRequest, UsageError
from tallybook.dates import parse_date
from tallybook.errors import TallybookError

TOP_ORDER = ["init", "db", "serve", "account", "tx", "query", "export", "journal", "import",
             "profile", "rules", "rate", "budget", "recurring", "report", "calc"]


def _load_commands():
    # Importing the modules registers their commands.
    from tallybook.cli import book_commands, calc_commands, data_commands  # noqa: F401


def _top_help():
    lines = [
        "usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS]",
        "",
        "Double-entry bookkeeping from the terminal.",
        "",
        "options:",
        "  --db FILE     the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE  what \"today\" is (default: the real date)",
        "  --version     print the version and stop",
        "  -h, --help    print this help and stop",
        "",
        "commands:",
    ]
    names = [w for w in TOP_ORDER if w in core.ROOT.children]
    names += [w for w in core.ROOT.children if w not in names]
    width = max(len(n) for n in names)
    for name in names:
        node = core.ROOT.children[name]
        if node.cmd is not None:
            text = node.cmd.summary
        else:
            text = " | ".join(node.children)
        lines.append(("  %s  %s" % (name.ljust(width), text)).rstrip())
    lines += ["", "Run 'tallybook COMMAND --help' for the usage of a command."]
    return "\n".join(lines) + "\n"


def _group_help(words, node):
    lines = ["usage: tallybook %s WORD [ARGUMENTS]" % " ".join(words), "", "words:"]
    width = max(len(w) for w in node.children)
    for word, child in node.children.items():
        if child.cmd is not None:
            text = child.cmd.summary
        else:
            text = " | ".join(child.children)
        lines.append(("  %s  %s" % (word.ljust(width), text)).rstrip())
    return "\n".join(lines) + "\n"


def _cmd_help(cmd):
    lines = ["usage: tallybook %s" % cmd.usage, "", cmd.summary]
    return "\n".join(lines) + "\n"


def _resolve(tokens):
    """Find the command for the leading words. Returns (words, node, rest)."""
    if not tokens:
        raise UsageError("no command given")
    node = core.ROOT
    words = []
    j = 0
    while True:
        if node.cmd is not None:
            return words, node, tokens[j:]
        if j >= len(tokens):
            raise UsageError("%s needs a word: %s" % (" ".join(words), ", ".join(node.children)))
        tok = tokens[j]
        if tok in ("-h", "--help") and words:
            return words, node, ["--help"]
        if tok in node.children:
            node = node.children[tok]
            words.append(tok)
            j += 1
            continue
        if tok.startswith("-"):
            raise UsageError("unknown option: %s" % tok)
        if words:
            raise UsageError("unknown word for %s: %s" % (" ".join(words), tok))
        raise UsageError("unknown command: %s" % tok)


def run(argv, stdin=None):
    """Run one command line. Returns (status, stdout_text, stderr_text)."""
    _load_commands()
    for tok in argv:
        try:
            tok.encode("utf-8")
        except UnicodeEncodeError:
            return 1, "", "tallybook: argument is not valid UTF-8 text\n"
    ctx = None
    try:
        db = None
        today = None
        seen = set()
        i = 0
        while i < len(argv):
            tok = argv[i]
            if tok == "--version":
                return 0, "tallybook %s\n" % __version__, ""
            if tok in ("-h", "--help"):
                return 0, _top_help(), ""
            name, eq, val = tok.partition("=")
            if name in ("--db", "--today"):
                if name in seen:
                    raise UsageError("option %s given twice" % name)
                seen.add(name)
                if not eq:
                    if i + 1 >= len(argv):
                        raise UsageError("option %s needs a value" % name)
                    val = argv[i + 1]
                    i += 1
                if name == "--db":
                    db = val
                else:
                    today = parse_date(val)
                i += 1
                continue
            if tok.startswith("-"):
                raise UsageError("unknown option: %s" % tok)
            break
        words, node, rest = _resolve(argv[i:])
        if node.cmd is None:
            return 0, _group_help(words, node), ""
        cmd = node.cmd
        try:
            args = core.parse_args(cmd, rest)
        except HelpRequest:
            return 0, _cmd_help(cmd), ""
        path = db if db is not None else (os.environ.get("TALLYBOOK_DB") or "tallybook.db")
        ctx = core.Context(path, today, stdin)
        result = cmd.handler(ctx, args)
        if isinstance(result, tuple):
            out, status = result
        else:
            out, status = result or "", 0
        return status, out, ""
    except UsageError as err:
        return 2, "", "tallybook: %s\nTry 'tallybook --help'.\n" % err
    except CliError as err:
        return 1, "", "".join(["tallybook: %s\n" % err.message] + ["%s\n" % ln for ln in err.lines])
    except TallybookError as err:
        return 1, "", "tallybook: %s\n" % err.message
    except RecursionError:
        return 1, "", "tallybook: input is too deeply nested\n"
    except MemoryError:
        return 1, "", "tallybook: out of memory\n"
    finally:
        if ctx is not None:
            ctx.close()


def _silence_stdout():
    try:
        fd = sys.stdout.fileno()
        os.dup2(os.open(os.devnull, os.O_WRONLY), fd)
    except (OSError, ValueError, AttributeError):
        pass


def _write(stream, text):
    if not text:
        return
    buf = getattr(stream, "buffer", None)
    if buf is not None:
        stream.flush()
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        stream.write(text)
        stream.flush()


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        status, out, err = run(argv)
    except KeyboardInterrupt:
        return 130
    except BaseException as exc:  # a bug must never print a traceback
        if isinstance(exc, SystemExit):
            raise
        status, out, err = 1, "", "tallybook: internal error: %s: %s\n" % (type(exc).__name__, exc)
    try:
        _write(sys.stdout, out)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        status, err = 1, "tallybook: cannot write output: %s\n" % (exc.strerror or exc)
    try:
        _write(sys.stderr, err)
    except (OSError, ValueError):
        pass
    return status


if __name__ == "__main__":
    sys.exit(main())

"""Output helpers shared by several command modules."""
from tallybook.dates import Period, format_date, last_day
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_json, transaction_to_dict
from tallybook.reports import (balance_sheet, cashflow, income_statement, register,
                               render_text, trial_balance)

REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def json_out(value):
    return to_json(value)


def table_out(headers, rows, align):
    """A table; no rows at all give no output (the caller prints '[]' for --json)."""
    rows = list(rows)
    if not rows:
        return ""
    return render_table(headers, rows, align)


def tx_list_text(txs):
    rows = [[t.id, format_date(t.date), t.flag, t.payee, t.narration,
        " ".join("#" + tag for tag in sorted(set(t.tags)))] for t in txs]
    return table_out(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def tx_list_out(txs, as_json):
    txs = list(txs)
    if as_json:
        return json_out([transaction_to_dict(t) for t in txs])
    return tx_list_text(txs)


def budget_lines_out(lines, as_json):
    lines = list(lines)
    if as_json:
        return json_out([ln.to_dict() for ln in lines])
    rows = [[ln.pattern, ln.period_kind, str(ln.budget), str(ln.actual), str(ln.remaining),
             "%s%%" % ln.percent, "over" if ln.over else ""] for ln in lines]
    return table_out(["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"],
                     rows, "llrrrrl")


def month_of(today):
    return Period(today.replace(day=1), today.replace(day=last_day(today.year, today.month)))


def build_report(kind, ledger, today, as_of=None, period=None, convert=None, account=None, rollup=False):
    """The report dict for a command-line/API report kind, with the documented defaults."""
    if kind == "trial-balance":
        return trial_balance(ledger, as_of)
    if kind == "balance-sheet":
        return balance_sheet(ledger, as_of if as_of is not None else today, convert, today)
    if kind == "income-statement":
        return income_statement(ledger, period if period is not None else month_of(today), convert)
    if kind == "cashflow":
        return cashflow(ledger, period if period is not None else month_of(today))
    if kind == "register":
        return register(ledger, account, period, rollup)
    raise ValidationError("unknown report '%s'" % (kind,))


def report_out(report, as_json):
    return json_out(report) if as_json else render_text(report)

