"""Importing a bank's CSV statement through a small profile."""
import re
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from tallybook.accounts import valid_path
from tallybook.currency import CURRENCIES
from tallybook.errors import ParseError, TallybookError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, parse_amount
from tallybook.rules import RuleSet, parse_rules

_BLANKS = " \t"
_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August",
           "September", "October", "November", "December"]
_DELIMITERS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_SETTINGS = ("date_column", "date_format", "payee_column", "narration_column", "amount_column",
             "debit_column", "credit_column", "currency", "account", "default_account",
             "delimiter", "skip_rows", "has_header", "negate", "decimal_separator",
             "thousands_separator", "flag", "tags")
_COLUMNS = ("date_column", "payee_column", "narration_column", "amount_column",
            "debit_column", "credit_column")


class CsvImportError(ParseError):
    def __init__(self, message="", line=None, detail=None):
        ParseError.__init__(self, message, detail)
        self.line = line


@dataclass
class ImportProfile:
    date_column: Optional[str] = None
    date_format: str = "%Y-%m-%d"
    payee_column: Optional[str] = None
    narration_column: Optional[str] = None
    amount_column: Optional[str] = None
    debit_column: Optional[str] = None
    credit_column: Optional[str] = None
    currency: Optional[str] = None
    account: Optional[str] = None
    default_account: Optional[str] = None
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
        if p.account == account and p.amount is not None:
            return (tx.date, p.amount.minor, p.amount.currency, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    if not isinstance(text, str):
        raise CsvImportError("csv text must be a string")
    if isinstance(profile, str):
        profile = parse_profile(profile)
    elif not isinstance(profile, ImportProfile):
        raise CsvImportError("profile must be an ImportProfile or profile text")
    if isinstance(rules, str):
        rules = parse_rules(rules)
    if rules is not None and not isinstance(rules, RuleSet):
        rules = RuleSet(list(rules))
    if text.startswith("﻿"):
        text = text[1:]
    text, dropped = _skip_lines(text, profile.skip_rows)
    records = _records(text, profile.delimiter, dropped + 1)

    specs = {"date": profile.date_column, "payee": profile.payee_column,
             "narration": profile.narration_column, "amount": profile.amount_column,
             "debit": profile.debit_column, "credit": profile.credit_column}
    header = []
    if profile.has_header:
        for _, cells, _ in records:
            if not _is_blank(cells):
                header = cells
                break
        else:
            raise CsvImportError("the file has no header row")
    cols = {}
    for key, spec in specs.items():
        if spec is None:
            cols[key] = None
            continue
        index = _find_column(spec, header)
        if index is None:
            raise CsvImportError("column '%s' is not in the header" % spec)
        cols[key] = index

    counts = {}
    for tx in existing:
        key = _key(tx, profile.account)
        if key is not None:
            counts[key] = counts.get(key, 0) + 1

    rx = _amount_regex(profile)
    result = ImportResult()
    seen = {}
    for number, cells, closed in records:
        if _is_blank(cells):
            continue
        try:
            if not closed:
                raise _Bad("unterminated quoted field")
            tx = _build_row(cells, cols, specs, profile, rx, rules)
        except _Bad as err:
            result.errors.append((number, str(err)))
            continue
        key = _key(tx, profile.account)
        seen[key] = seen.get(key, 0) + 1
        if seen[key] <= counts.get(key, 0):
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out


class RuleSet:
    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def match(self, fields):
        for rule in self._rules:
            if rule.holds(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        return None if rule is None else rule.effect()

    def categorize(self, tx):
        postings = list(tx.postings)
        fields = {
            "payee": tx.payee,
            "narration": tx.narration,
            "date": tx.date,
            "amount": postings[0].amount if postings else None,
        }
        effect = self.apply(fields)
        if effect is None:
            return tx
        if "account" in effect and len(postings) == 2:
            second = postings[1]
            postings[1] = Posting(effect["account"], second.amount, second.note)
        tags = tuple(sorted(set(tx.tags) | set(effect.get("tags", ()))))
        return Transaction(tx.date, effect.get("payee", tx.payee),
                           effect.get("narration", tx.narration), postings, tags,
                           effect.get("flag", tx.flag), tx.id)


"""Recurring transactions: schedules in plain words and dated copies of a template."""
import re
from datetime import date, timedelta

from tallybook.currency import is_date
from tallybook.dates import DateError, add_months, format_date, last_day, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Transaction

_DAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_DAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August",
                "September", "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}
_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")

SHAPES = ("daily, weekly on mon, monthly on 5, monthly on last, yearly on 03-15, "
          "every N days|weeks|months|years from YYYY-MM-DD")


class RecurringError(ValidationError):
    pass


def _bad(text):
    return RecurringError("invalid schedule %r: use one of %s" % (text, SHAPES))


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Schedule:
    """An immutable rhythm. ``kind`` is daily, weekly, monthly, yearly or every."""

    __slots__ = ("_key",)

    def __init__(self, key):
        object.__setattr__(self, "_key", key)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __eq__(self, other):
        return isinstance(other, Schedule) and self._key == other._key

    def __ne__(self, other):
        return not self == other

    def __hash__(self):
        return hash(self._key)

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    def __str__(self):
        k = self._key
        if k[0] == "daily":
            return "daily"
        if k[0] == "weekly":
            return "weekly on %s" % _DAYS[k[1]]
        if k[0] == "monthly":
            return "monthly on %s" % ("last" if k[1] == 0 else k[1])
        if k[0] == "yearly":
            return "yearly on %02d-%02d" % (k[1], k[2])
        n, unit, start = k[1], k[2], k[3]
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", format_date(start))

    @property
    def kind(self):
        return self._key[0]

    def _dates_from(self, start):
        """Ascending dates of the schedule on or after ``start``; ends at the calendar's end."""
        k = self._key
        try:
            if k[0] == "daily":
                d = start
                while True:
                    yield d
                    d += timedelta(days=1)
            elif k[0] == "weekly":
                d = start + timedelta(days=(k[1] - start.weekday()) % 7)
                while True:
                    yield d
                    d += timedelta(days=7)
            elif k[0] == "monthly":
                year, month = start.year, start.month
                while year <= 9999:
                    day = last_day(year, month) if k[1] == 0 else min(k[1], last_day(year, month))
                    d = date(year, month, day)
                    if d >= start:
                        yield d
                    month += 1
                    if month > 12:
                        year, month = year + 1, 1
            elif k[0] == "yearly":
                year = start.year
                while year <= 9999:
                    day = min(k[2], last_day(year, k[1]))
                    d = date(year, k[1], day)
                    if d >= start:
                        yield d
                    year += 1
            else:
                n, unit, origin = k[1], k[2], k[3]
                if unit in ("day", "week"):
                    step = n * (1 if unit == "day" else 7)
                    gap = (start - origin).days
                    i = 0 if gap <= 0 else -(-gap // step)
                    d = origin + timedelta(days=i * step)
                    while True:
                        yield d
                        d += timedelta(days=step)
                else:
                    step = n * (1 if unit == "month" else 12)
                    gap = (start.year - origin.year) * 12 + start.month - origin.month
                    i = max(0, gap // step - 1)
                    while True:
                        d = add_months(origin, i * step)
                        if d >= start:
                            yield d
                        i += 1
        except (OverflowError, DateError, ValueError):
            return

    def between(self, start, end):
        if not is_date(start) or not is_date(end):
            raise RecurringError("between needs two dates")
        out = []
        for d in self._dates_from(start):
            if d > end:
                break
            out.append(d)
        return out

    return "every %d %ss from %s" % (n, unit, format_date(origin))


class Recurring:
    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise RecurringError("invalid name %r: use letters, digits, - and _, not starting with - or _" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("schedule must be a Schedule or text, not %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, not %r" % (template,))
        if not is_date(start):
            raise RecurringError("start must be a date, not %r" % (start,))
        if end is not None:
            if not is_date(end):
                raise RecurringError("end must be a date, not %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (format_date(end), format_date(start)))
        if count is not None and (not _is_int(count) or count < 1):
            raise RecurringError("count must be a whole number of at least 1, not %r" % (count,))
        for attr, value in (("_name", name), ("_schedule", schedule), ("_template", template),
                            ("_start", start), ("_end", end), ("_count", count)):
            object.__setattr__(self, attr, value)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def _fields(self):
        return (self._name, self._schedule, self._template, self._start, self._end, self._count)

    def __eq__(self, other):
        return isinstance(other, Recurring) and self._fields() == other._fields()

    def __ne__(self, other):
        return not self == other

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, %r)" % (self._name, str(self._schedule))


def _series(rec, start):
    """Dates of the series on or after ``start`` (never before rec.start), honouring end and count."""
    first = max(start, rec.start) if rec.count is None else rec.start
    produced = 0
    for d in rec.schedule._dates_from(first):
        if rec.end is not None and d > rec.end:
            return
        if rec.count is not None and produced >= rec.count:
            return
        produced += 1
        if d >= start:
            yield d


def occurrences(rec, start, end):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(start) or not is_date(end):
        raise RecurringError("occurrences needs two dates")
    out = []
    if end < start:
        return out
    for d in _series(rec, start):
        if d > end:
            break
        out.append(d)
    return out


def next_occurrence(rec, after):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(after):
        raise RecurringError("after must be a date, not %r" % (after,))
    if after >= date.max:
        return None
    for d in _series(rec, after + timedelta(days=1)):
        return d
    return None


def instantiate(rec, on):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(on):
        raise RecurringError("on must be a date, not %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    recs = list(recs)
    found = []
    for position, rec in enumerate(recs):
        if not isinstance(rec, Recurring):
            raise RecurringError("not a recurring item: %r" % (rec,))
        for d in occurrences(rec, start, end):
            found.append((d, rec.name, position))
    found.sort()
    return [instantiate(recs[position], d) for d, _, position in found]


def _one_line(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -----------------------------------------------------
    def _prepare(self, tx, ids_in_use):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, not %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("invalid flag %r: use * or !" % (tx.flag,))
        if not _one_line(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _one_line(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if not isinstance(tx.tags, (list, tuple, set, frozenset)):
            raise LedgerError("tags must be a list of names")
        for tag in tx.tags:
            if not isinstance(tag, str) or not _TAG.fullmatch(tag):
                raise LedgerError("invalid tag %r" % (tag,))
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _one_line(p.note):
                raise LedgerError("a posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("a posting amount must be money or None")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account,))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
            self._check_currency(p.account, p.amount)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = []
            for cur in off:
                amount = Money(-sums[cur], cur)
                self._check_currency(gap.account, amount)
                filled.append(Posting(gap.account, amount, gap.note))
            postings[i:i + 1] = filled
        elif off:
            raise LedgerError("transaction does not balance: " + ", ".join(
                "%s %s" % (c, format_minor(sums[c], c)) for c in off))
        if tx.id is None:
            new_id = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in ids_in_use:
                raise LedgerError("transaction id %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings,
                           tuple(sorted(set(tx.tags))), tx.flag, new_id)

    def _check_currency(self, account, amount):
        if amount is None:
            return
        held = self.chart.get(account).currency
        if held is not None and held != amount.currency:
            raise LedgerError("account %s only holds %s, not %s" % (account, held, amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._prepare(tx, self._txs)
        self._store(stored)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise

