            tokens, comment = _scan(line)
            if line[0] in _BLANKS:
                if current is None:
                    raise _Bad("indented line outside a transaction")
                current.postings.append(_parse_posting(tokens, comment))
                continue
            current = None
            head = tokens[0] if tokens else None
            if head == ("w", "account"):
                acc = _parse_account(tokens)
                if acc.path in seen:
                    raise _Bad("account %s is declared twice" % acc.path)
