# -- calendar arithmetic on month indexes ------------------------------------

def _first_ordinal(month_index):
    year, month = divmod(month_index, 12)
    if year > 9999:
        return date.max.toordinal() + 1
    return date(year, month + 1, 1).toordinal()


def _allowance(budget, period):
    """The allowance in the asked period, or None when the budget is not in force."""
    step = _STEP[budget.period_kind]
    first = budget.start.year * 12 + budget.start.month - 1
    first -= first % step
    first_ord = _first_ordinal(first)
    p_start, p_end = period.start.toordinal(), period.end.toordinal()
    if p_end < first_ord:
        return None
    lo = max(p_start, first_ord)
    date_lo = date.fromordinal(lo)
    idx = date_lo.year * 12 + date_lo.month - 1
    idx -= idx % step
    total = Fraction(0)
    begin = _first_ordinal(idx)
    while begin <= p_end:
        nxt = _first_ordinal(idx + step)
        overlap = min(p_end, nxt - 1) - max(p_start, begin) + 1
        if overlap > 0:
            total += Fraction(overlap, nxt - begin)
        idx += step
        begin = nxt
    scaled = total * budget.amount.minor
    return Money(round_div(scaled.numerator, scaled.denominator), budget.amount.currency)


def _percent(actual, allowance):
    if allowance == 0:
        return Decimal("0.0") if actual == 0 else Decimal("100.0")
    tenths = round_div(actual * 1000, allowance)
    sign = "-" if tenths < 0 else ""
    whole, frac = divmod(abs(tenths), 10)
    return Decimal("%s%d.%d" % (sign, whole, frac))


def budget_status(budgets, ledger, period):
    if not isinstance(period, Period):
        raise BudgetError("period must be a Period, not %r" % (period,))
    budgets = list(budgets)
    for b in budgets:
        if not isinstance(b, Budget):
            raise BudgetError("not a budget: %r" % (b,))
    spent = {}
    for tx, posting in ledger.postings():
        if posting.amount is None or not period.contains(tx.date):
            continue
        key = (posting.account, posting.amount.currency)
        spent[key] = spent.get(key, 0) + posting.amount.minor
    ordered = sorted(budgets, key=lambda b: (b.pattern, _KINDS.index(b.period_kind), b.start))
    lines = []
    for b in ordered:
        allowance = _allowance(b, period)
        if allowance is None:
            continue
        cur = b.amount.currency
        per_account = sorted(
            (acct, minor) for (acct, c), minor in spent.items()
            if c == cur and minor != 0 and b.matches(acct)
        )
        actual = Money(sum(minor for _, minor in per_account), cur)
        lines.append(BudgetLine(
            b.pattern, b.period_kind, allowance, actual, allowance - actual,
            _percent(actual.minor, allowance.minor), actual.minor > allowance.minor,
            tuple((acct, Money(minor, cur)) for acct, minor in per_account),
        ))
    return lines
