"""``tallybook calc ...``: the library on the command line, never touching a book."""
from datetime import date, timedelta
from fractions import Fraction

from tallybook.accounts import account_type, parent_path, path_matches
from tallybook.budgets import Budget, budget_status
from tallybook.cli.core import (CliError, Opt, UsageError, command, input_label, parse_int,
                                wrap_input_errors)
from tallybook.cli.render import (REPORT_KINDS, budget_lines_out, build_report, report_out,
                                  tx_list_out)
from tallybook.csvimport import import_csv, parse_profile
from tallybook.currency import RateTable
from tallybook.dates import Period, add_months, format_date, parse_date, periods
from tallybook.journal import Journal, format_journal, parse_journal
from tallybook.model import Transaction
from tallybook.money import Money, format_minor
from tallybook.query import parse_query, select
from tallybook.recurring import Recurring, occurrences, parse_schedule
from tallybook.rules import parse_rules

WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
MAX_PERIODS = 5000
MAX_SCHEDULE_SPAN = 40000
# ``calc money convert`` needs a date for its one-rate table; it never shows.
CONVERT_DATE = date(2000, 1, 1)


def _lines(items):
    items = list(items)
    return "".join(item + "\n" for item in items)


def _read(ctx, path):
    return ctx.read_input(path)


# -- money ---------------------------------------------------------------------

@command("calc money parse", usage="calc money parse MONEY",
         summary="print the minor units and currency of an amount", pos=[("MONEY", "1")],
         needs_book=False)
def money_parse(ctx, args):
    money = Money.parse(args.pos[0])
    return "%d %s\n" % (money.minor, money.currency)


@command("calc money format", usage="calc money format MINOR CUR",
         summary="write minor units as an amount", pos=[("MINOR", "1"), ("CUR", "1")],
         needs_book=False)
def money_format(ctx, args):
    minor = parse_int(args.pos[0], "minor units", negative=True)
    cur = args.pos[1]
    return "%s %s\n" % (format_minor(minor, cur), cur)


@command("calc money add", usage="calc money add A B", summary="add two amounts",
         pos=[("A", "1"), ("B", "1")], needs_book=False)
def money_add(ctx, args):
    return "%s\n" % (Money.parse(args.pos[0]) + Money.parse(args.pos[1]))


@command("calc money sub", usage="calc money sub A B", summary="subtract B from A",
         pos=[("A", "1"), ("B", "1")], needs_book=False)
