                   "days: %d" % period.days, "label: %s" % period.label, "next: %s" % nxt.label])


def _period_count(start, end, step):
    """How many periods ``periods(start, end, step)`` would give, without building them."""
    if step == "week":
        first = start.toordinal() - start.weekday()
        last = end.toordinal() - end.weekday()
        return (last - first) // 7 + 1
    months = (end.year * 12 + end.month) - (start.year * 12 + start.month)
    if step == "month":
        return months + 1
    if step == "quarter":
        return (end.year * 12 + (end.month - 1) // 3 * 3 - (start.year * 12 + (start.month - 1) // 3 * 3)) // 3 + 1
    return end.year - start.year + 1


@command("calc date periods", usage="calc date periods START END STEP",
         summary="list the periods covering START to END (week, month, quarter, year)",
         pos=[("START", "1"), ("END", "1"), ("STEP", "1")], needs_book=False)
