    step = args.pos[2]
    if step in ("week", "month", "quarter", "year") and end >= start:
        if _period_count(start, end, step) > MAX_PERIODS:
            raise CliError("more than %d periods" % MAX_PERIODS)
    return _lines(p.label for p in periods(start, end, step))


