               Opt("start", metavar="DATE"), Opt("end", metavar="DATE"), Opt("count", metavar="N")],
         pos=[("SCHEDULE", "1")], needs_book=False)
def schedule(ctx, args):
    sched = parse_schedule(args.pos[0])
