    end = parse_date(args.get("end")) if args.get("end") is not None else None
    count = parse_int(args.get("count"), "count", negative=True) if args.get("count") is not None else None
    if (window_to - min(window_from, start)).days > MAX_SCHEDULE_SPAN:
        raise CliError("the window is longer than %d days" % MAX_SCHEDULE_SPAN)
    template = Transaction(start, "calc")
