@command("calc rules", usage="calc rules FILE [--payee TEXT] [--narration TEXT] [--amount MONEY] [--date DATE]",
         summary="which rule of a rules file wins for some fields",
         opts=[Opt("payee", metavar="TEXT"), Opt("narration", metavar="TEXT"),
               Opt("amount", metavar="MONEY"), Opt("date", metavar="DATE")],
         pos=[("FILE", "1")], needs_book=False)
def rules_command(ctx, args):
    path = args.pos[0]
    fields = {}
    if args.get("payee") is not None:
        fields["payee"] = args.get("payee")
    if args.get("narration") is not None:
        fields["narration"] = args.get("narration")
    if args.get("amount") is not None:
        fields["amount"] = Money.parse(args.get("amount"))
    if args.get("date") is not None:
        fields["date"] = parse_date(args.get("date"))
    rules = wrap_input_errors(path, parse_rules, _read(ctx, path))
