    for key in ("account", "payee", "narration", "flag"):
        if key in effect:
            out.append(("%s: %s" % (key, effect[key])).rstrip(" "))
    if "tags" in effect:
        out.append("tags: " + ",".join(effect["tags"]))
    return _lines(out)


