@command("calc budget", usage="calc budget PATTERN AMOUNT --journal FILE --period PERIOD [--per KIND] [--start DATE] [--json]",
         summary="one budget measured over a period of a journal",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("period", required=True, metavar="PERIOD"),
               Opt("per", metavar="KIND"), Opt("start", metavar="DATE"), Opt("json", "flag")],
         pos=[("PATTERN", "1"), ("AMOUNT", "1")], needs_book=False)
def budget_command(ctx, args):
    period = Period.parse(args.get("period"))
    amount = Money.parse(args.pos[1])
    start = parse_date(args.get("start")) if args.get("start") is not None else period.start
    budget = Budget(args.pos[0], args.get("per", "month"), amount, start)
    ledger = _ledger(ctx, args.get("journal"))
    return budget_lines_out(budget_status([budget], ledger, period), args.flag("json"))


@command("calc report", usage="calc report KIND [ACCOUNT] --journal FILE [--as-of DATE] [--period PERIOD] [--convert CUR] [--rollup] [--json]",
         summary="a report of a journal (trial-balance, balance-sheet, income-statement, cashflow, register)",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("as-of", metavar="DATE"),
               Opt("period", metavar="PERIOD"), Opt("convert", metavar="CUR"),
               Opt("rollup", "flag"), Opt("json", "flag")],
         pos=[("KIND", "1"), ("ACCOUNT", "?")], needs_book=False)
def report_command(ctx, args):
    kind = args.pos[0]
    if kind not in REPORT_KINDS:
        raise UsageError("unknown report: %s" % kind)
    account = args.pos[1] if len(args.pos) > 1 else None
    if kind == "register" and account is None:
        raise UsageError("missing argument ACCOUNT")
    # Only what belongs to the kind is looked at; the rest is ignored.
    as_of = period = convert = None
    if kind in ("trial-balance", "balance-sheet") and args.get("as-of") is not None:
        as_of = parse_date(args.get("as-of"))
    if kind in ("income-statement", "cashflow", "register") and args.get("period") is not None:
        period = Period.parse(args.get("period"))
    if kind in ("balance-sheet", "income-statement"):
        convert = args.get("convert")
    ledger = _ledger(ctx, args.get("journal"))
    report = build_report(kind, ledger, ctx.today, as_of=as_of, period=period, convert=convert,
                          account=account, rollup=args.flag("rollup") and kind == "register")
    return report_out(report, args.flag("json"))


@command("calc csv", usage="calc csv PROFILE_FILE CSV_FILE [--rules FILE]",
         summary="what importing a bank statement would produce, as journal text",
         opts=[Opt("rules", metavar="FILE")], pos=[("PROFILE_FILE", "1"), ("CSV_FILE", "1")],
         needs_book=False)
def csv_command(ctx, args):
    profile_path, csv_path = args.pos
    profile = wrap_input_errors(profile_path, parse_profile, _read(ctx, profile_path))
    rules = None
    if args.get("rules") is not None:
        rules_path = args.get("rules")
        rules = wrap_input_errors(rules_path, parse_rules, _read(ctx, rules_path))
    statement = _read(ctx, csv_path)
    result = wrap_input_errors(csv_path, import_csv, statement, profile, rules)
    if result.errors:
        raise CliError("%d rows could not be converted" % len(result.errors),
                       lines=["row %d: %s" % (number, message) for number, message in result.errors])
    return format_journal(Journal(transactions=list(result.transactions)))

