"""``tallybook calc ...``: the library on the command line, never touching a book."""
from datetime import date, timedelta
from fractions import Fraction

from tallybook.accounts import account_type, parent_path, path_matches
from tallybook.budgets import Budget, budget_status
from tallybook.cli.core import (CliError, Opt, UsageError, command, input_label, parse_int,
                                wrap_input_errors)
from tallybook.cli.render import (REPORT_KINDS, budget_lines_out, build_report, report_out,
                                  tx_list_out)
from tallybook.csvimport import import_csv, parse_profile
from tallybook.currency import RateTable
from tallybook.dates import Period, add_months, format_date, parse_date, periods
from tallybook.journal import Journal, format_journal, parse_journal
from tallybook.model import Transaction
from tallybook.money import Money, format_minor
from tallybook.query import parse_query, select
from tallybook.recurring import Recurring, occurrences, parse_schedule
from tallybook.rules import parse_rules

WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
MAX_PERIODS = 5000
MAX_SCHEDULE_SPAN = 40000
# ``calc money convert`` needs a date for its one-rate table; it never shows.
CONVERT_DATE = date(2000, 1, 1)


def _lines(items):
    items = list(items)
    return "".join(item + "\n" for item in items)


def _read(ctx, path):
    return ctx.read_input(path)


# -- money ---------------------------------------------------------------------

@command("calc money parse", usage="calc money parse MONEY",
         summary="print the minor units and currency of an amount", pos=[("MONEY", "1")],
         needs_book=False)
def money_parse(ctx, args):
    money = Money.parse(args.pos[0])
    return "%d %s\n" % (money.minor, money.currency)


@command("calc money format", usage="calc money format MINOR CUR",
         summary="write minor units as an amount", pos=[("MINOR", "1"), ("CUR", "1")],
         needs_book=False)
def money_format(ctx, args):
    minor = parse_int(args.pos[0], "minor units", negative=True)
    cur = args.pos[1]
    return "%s %s\n" % (format_minor(minor, cur), cur)


@command("calc money add", usage="calc money add A B", summary="add two amounts",
         pos=[("A", "1"), ("B", "1")], needs_book=False)
def money_add(ctx, args):
    return "%s\n" % (Money.parse(args.pos[0]) + Money.parse(args.pos[1]))


@command("calc money sub", usage="calc money sub A B", summary="subtract B from A",
         pos=[("A", "1"), ("B", "1")], needs_book=False)
def money_sub(ctx, args):
    return "%s\n" % (Money.parse(args.pos[0]) - Money.parse(args.pos[1]))


@command("calc money scale", usage="calc money scale MONEY RATIO",
         summary="multiply an amount by N or N/D, rounded", pos=[("MONEY", "1"), ("RATIO", "1")],
         needs_book=False)
def money_scale(ctx, args):
    money = Money.parse(args.pos[0])
    num_text, slash, den_text = args.pos[1].partition("/")
    num = parse_int(num_text, "ratio", negative=True)
    den = parse_int(den_text, "ratio", negative=True) if slash else 1
    return "%s\n" % money.scale(num, den)


@command("calc money allocate", usage="calc money allocate MONEY WEIGHT...",
         summary="split an amount fairly by weights", pos=[("MONEY", "1"), ("WEIGHT", "+")],
         needs_book=False)
def money_allocate(ctx, args):
    money = Money.parse(args.pos[0])
    weights = [parse_int(w, "weight", negative=True) for w in args.pos[1:]]
    return _lines(str(part) for part in money.allocate(weights))


@command("calc money convert", usage="calc money convert MONEY TO RATE",
         summary="convert an amount at one rate", pos=[("MONEY", "1"), ("TO", "1"), ("RATE", "1")],
         needs_book=False)
def money_convert(ctx, args):
    money = Money.parse(args.pos[0])
    table = RateTable()
    table.set(money.currency, args.pos[1], args.pos[2], CONVERT_DATE)
    return "%s\n" % table.convert(money, args.pos[1], CONVERT_DATE)


# -- dates ---------------------------------------------------------------------

@command("calc date parse", usage="calc date parse DATE", summary="print a date and its weekday",
         pos=[("DATE", "1")], needs_book=False)
def date_parse(ctx, args):
    day = parse_date(args.pos[0])
    return "%s %s\n" % (format_date(day), WEEKDAYS[day.weekday()])


@command("calc date add-months", usage="calc date add-months DATE N",
         summary="move a date by whole months", pos=[("DATE", "1"), ("N", "1")], needs_book=False)
def date_add_months(ctx, args):
    day = parse_date(args.pos[0])
    n = parse_int(args.pos[1], "number of months", negative=True)
    return "%s\n" % format_date(add_months(day, n))


@command("calc date period", usage="calc date period PERIOD",
         summary="print the start, end, length, label and successor of a period",
         pos=[("PERIOD", "1")], needs_book=False)
def date_period(ctx, args):
    period = Period.parse(args.pos[0])
    nxt = period.next()
    return _lines(["start: %s" % format_date(period.start), "end: %s" % format_date(period.end),
                   "days: %d" % period.days, "label: %s" % period.label, "next: %s" % nxt.label])


def _period_count(start, end, step):
    """How many periods ``periods(start, end, step)`` would give, without building them."""
    if step == "week":
        first = start.toordinal() - start.weekday()
        last = end.toordinal() - end.weekday()
        return (last - first) // 7 + 1
    months = (end.year * 12 + end.month) - (start.year * 12 + start.month)
    if step == "month":
        return months + 1
    if step == "quarter":
        return (end.year * 12 + (end.month - 1) // 3 * 3 - (start.year * 12 + (start.month - 1) // 3 * 3)) // 3 + 1
    return end.year - start.year + 1


@command("calc date periods", usage="calc date periods START END STEP",
         summary="list the periods covering START to END (week, month, quarter, year)",
         pos=[("START", "1"), ("END", "1"), ("STEP", "1")], needs_book=False)
def date_periods(ctx, args):
    start = parse_date(args.pos[0])
    end = parse_date(args.pos[1])
    step = args.pos[2]
    if step in ("week", "month", "quarter", "year") and end >= start:
        if _period_count(start, end, step) > MAX_PERIODS:
            raise CliError("more than %d periods" % MAX_PERIODS)
    return _lines(p.label for p in periods(start, end, step))


@command("calc schedule", usage="calc schedule SCHEDULE --from DATE --to DATE [--start DATE] [--end DATE] [--count N]",
         summary="the dates of a recurring schedule inside a window",
         opts=[Opt("from", required=True, metavar="DATE"), Opt("to", required=True, metavar="DATE"),
               Opt("start", metavar="DATE"), Opt("end", metavar="DATE"), Opt("count", metavar="N")],
         pos=[("SCHEDULE", "1")], needs_book=False)
def schedule(ctx, args):
    sched = parse_schedule(args.pos[0])
    window_from = parse_date(args.get("from"))
    window_to = parse_date(args.get("to"))
    start = parse_date(args.get("start")) if args.get("start") is not None else window_from
    end = parse_date(args.get("end")) if args.get("end") is not None else None
    count = parse_int(args.get("count"), "count", negative=True) if args.get("count") is not None else None
    if (window_to - min(window_from, start)).days > MAX_SCHEDULE_SPAN:
        raise CliError("the window is longer than %d days" % MAX_SCHEDULE_SPAN)
    template = Transaction(start, "calc")
    item = Recurring("calc", sched, template, start, end, count)
    return _lines(format_date(d) for d in occurrences(item, window_from, window_to))


# -- accounts and rules -----------------------------------------------------------

@command("calc account check", usage="calc account check PATH",
         summary="check an account path and print its type and parent", pos=[("PATH", "1")],
         needs_book=False)
def account_check(ctx, args):
    path = args.pos[0]
    kind = account_type(path)
    parent = parent_path(path)
    return _lines(["path: %s" % path, "type: %s" % kind, "parent: %s" % (parent or "none")])


@command("calc account match", usage="calc account match PATTERN PATH",
         summary="say whether an account pattern matches a path",
         pos=[("PATTERN", "1"), ("PATH", "1")], needs_book=False)
def account_match(ctx, args):
    return "yes\n" if path_matches(args.pos[0], args.pos[1]) else "no\n"


@command("calc rules", usage="calc rules FILE [--payee TEXT] [--narration TEXT] [--amount MONEY] [--date DATE]",
         summary="which rule of a rules file wins for some fields",
         opts=[Opt("payee", metavar="TEXT"), Opt("narration", metavar="TEXT"),
               Opt("amount", metavar="MONEY"), Opt("date", metavar="DATE")],
         pos=[("FILE", "1")], needs_book=False)
def rules_command(ctx, args):
    path = args.pos[0]
    fields = {}
    if args.get("payee") is not None:
        fields["payee"] = args.get("payee")
    if args.get("narration") is not None:
        fields["narration"] = args.get("narration")
    if args.get("amount") is not None:
        fields["amount"] = Money.parse(args.get("amount"))
    if args.get("date") is not None:
        fields["date"] = parse_date(args.get("date"))
    rules = wrap_input_errors(path, parse_rules, _read(ctx, path))
    rule = rules.match(fields)
    if rule is None:
        return "no match\n"
    effect = rule.effect()
    out = ["rule: %d" % rule.line]
    for key in ("account", "payee", "narration", "flag"):
        if key in effect:
            out.append(("%s: %s" % (key, effect[key])).rstrip(" "))
    if "tags" in effect:
        out.append("tags: " + ",".join(effect["tags"]))
    return _lines(out)


# -- journal files ----------------------------------------------------------------

def _read_journal(ctx, path):
    return wrap_input_errors(path, parse_journal, _read(ctx, path))


@command("calc journal check", usage="calc journal check FILE",
         summary="read a journal file and check it as a book", pos=[("FILE", "1")], needs_book=False)
def journal_check(ctx, args):
    journal = _read_journal(ctx, args.pos[0])
    journal.to_ledger()
    return "ok: %d accounts, %d rates, %d transactions\n" % (
        len(journal.accounts), len(journal.rates), len(journal.transactions))


@command("calc journal format", usage="calc journal format FILE",
         summary="print the canonical text of a journal file", pos=[("FILE", "1")], needs_book=False)
def journal_format(ctx, args):
    return format_journal(_read_journal(ctx, args.pos[0]))


def _ledger(ctx, path):
    return _read_journal(ctx, path).to_ledger()


@command("calc query", usage="calc query QUERY --journal FILE [--json]",
         summary="the transactions of a journal matching a query",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("json", "flag")],
         pos=[("QUERY", "1")], needs_book=False)
def query_command(ctx, args):
    ledger = _ledger(ctx, args.get("journal"))
    query = parse_query(args.pos[0], ledger.chart)
    return tx_list_out(select(ledger.transactions(), query), args.flag("json"))


@command("calc rate", usage="calc rate FROM TO --journal FILE --on DATE",
         summary="the exchange rate a journal gives, as a fraction",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("on", required=True, metavar="DATE")],
         pos=[("FROM", "1"), ("TO", "1")], needs_book=False)
def rate_command(ctx, args):
    on = parse_date(args.get("on"))
    ledger = _ledger(ctx, args.get("journal"))
    rate = Fraction(ledger.rates.rate(args.pos[0], args.pos[1], on))
    return "%d/%d\n" % (rate.numerator, rate.denominator)


@command("calc budget", usage="calc budget PATTERN AMOUNT --journal FILE --period PERIOD [--per KIND] [--start DATE] [--json]",
         summary="one budget measured over a period of a journal",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("period", required=True, metavar="PERIOD"),
               Opt("per", metavar="KIND"), Opt("start", metavar="DATE"), Opt("json", "flag")],
         pos=[("PATTERN", "1"), ("AMOUNT", "1")], needs_book=False)
def budget_command(ctx, args):
    period = Period.parse(args.get("period"))
    amount = Money.parse(args.pos[1])
    start = parse_date(args.get("start")) if args.get("start") is not None else period.start
    budget = Budget(args.pos[0], args.get("per", "month"), amount, start)
    ledger = _ledger(ctx, args.get("journal"))
    return budget_lines_out(budget_status([budget], ledger, period), args.flag("json"))


@command("calc report", usage="calc report KIND [ACCOUNT] --journal FILE [--as-of DATE] [--period PERIOD] [--convert CUR] [--rollup] [--json]",
         summary="a report of a journal (trial-balance, balance-sheet, income-statement, cashflow, register)",
         opts=[Opt("journal", required=True, metavar="FILE"), Opt("as-of", metavar="DATE"),
               Opt("period", metavar="PERIOD"), Opt("convert", metavar="CUR"),
               Opt("rollup", "flag"), Opt("json", "flag")],
         pos=[("KIND", "1"), ("ACCOUNT", "?")], needs_book=False)
def report_command(ctx, args):
    kind = args.pos[0]
    if kind not in REPORT_KINDS:
        raise UsageError("unknown report: %s" % kind)
    account = args.pos[1] if len(args.pos) > 1 else None
    if kind == "register" and account is None:
        raise UsageError("missing argument ACCOUNT")
    # Only what belongs to the kind is looked at; the rest is ignored.
    as_of = period = convert = None
    if kind in ("trial-balance", "balance-sheet") and args.get("as-of") is not None:
        as_of = parse_date(args.get("as-of"))
    if kind in ("income-statement", "cashflow", "register") and args.get("period") is not None:
        period = Period.parse(args.get("period"))
    if kind in ("balance-sheet", "income-statement"):
        convert = args.get("convert")
    ledger = _ledger(ctx, args.get("journal"))
    report = build_report(kind, ledger, ctx.today, as_of=as_of, period=period, convert=convert,
                          account=account, rollup=args.flag("rollup") and kind == "register")
    return report_out(report, args.flag("json"))


@command("calc csv", usage="calc csv PROFILE_FILE CSV_FILE [--rules FILE]",
         summary="what importing a bank statement would produce, as journal text",
         opts=[Opt("rules", metavar="FILE")], pos=[("PROFILE_FILE", "1"), ("CSV_FILE", "1")],
         needs_book=False)
def csv_command(ctx, args):
    profile_path, csv_path = args.pos
    profile = wrap_input_errors(profile_path, parse_profile, _read(ctx, profile_path))
    rules = None
    if args.get("rules") is not None:
        rules_path = args.get("rules")
        rules = wrap_input_errors(rules_path, parse_rules, _read(ctx, rules_path))
    statement = _read(ctx, csv_path)
    result = wrap_input_errors(csv_path, import_csv, statement, profile, rules)
    if result.errors:
        raise CliError("%d rows could not be converted" % len(result.errors),
                       lines=["row %d: %s" % (number, message) for number, message in result.errors])
    return format_journal(Journal(transactions=list(result.transactions)))
